        add: (c) => { if (!c) return; try { const s = window.__jbHiddenReg.get(); s.add(window.__jbHiddenReg.__key(c)); GM_setValue('jb_hidden_codes', JSON.stringify([...s])); } catch (e) {} },
        del: (c) => { if (!c) return; try { const s = window.__jbHiddenReg.get(); s.delete(window.__jbHiddenReg.__key(c)); GM_setValue('jb_hidden_codes', JSON.stringify([...s])); } catch (e) {} },
        has: (c) => { if (!c) return false; return window.__jbHiddenReg.get().has(window.__jbHiddenReg.__key(c)); }
