    // ========== javdb 站自身 vue-i18n 缺 key 自动修复 ==========
    // javdb 前端偶发把翻译 key 直接渲染出来（如演员页"載入更多"按钮显示 [missing "en-more" translation]，
    // 点击后 Vue 重渲染即恢复）——这是 javdb 自家 i18n 字典缺失，与扩展无关。
    // 此处做外观级修复：MutationObserver 只扫新增节点，命中 [missing "xxx-more" translation] 时
    // 按页面语言替换为正常文案；非 -more 类 key 不动，避免误改。
// [第299轮·用户实测] javdb 登录成功后部分浏览器（Edge 等）停在 /login 不跳转（无扩展也复现=网站自身行为差异），
    // 且站上已亮「登入成功」提示——扩展兜底：登录页检测到成功提示后自动回首页。
    (function jbLoginAutoRedirect() {
        if (!/javdb/i.test(location.hostname)) return;
        if (!/^\/login/.test(location.pathname)) return;
        let done = false;
        const timer = setInterval(() => {
            if (done) { clearInterval(timer); return; }
            try {
                const txt = document.body ? document.body.innerText : '';
                if (/登入成功|登錄成功|登录成功|登陸成功/i.test(txt)) {
                    done = true; clearInterval(timer);
                    setTimeout(() => { try { location.replace('/'); } catch (e) {} }, 900);
                }
            } catch (e) {}
        }, 600);
        setTimeout(() => { done = true; }, 30000);
    })();
    function jbFixI18nMissingText(root) {
        try {
            const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
            let n;
            while ((n = walker.nextNode())) {
                const t = n.nodeValue;
                if (!t || t.indexOf('[missing ') < 0) continue;
                const m = t.match(/\[missing "([a-z0-9_.-]+)" translation\]/i);
                if (!m) continue;
                const lang = (document.documentElement.lang || '').toLowerCase();
                let text = '';
                if (/-more$/.test(m[1])) text = /en/.test(lang) ? 'Load more' : (/(tw|hk)/.test(lang) ? '載入更多' : '载入更多');
                else if (/\.(collapse|expand)$/.test(m[1])) text = /en/.test(lang) ? 'More' : (/(tw|hk)/.test(lang) ? '更多' : '更多');
                else continue;
                n.nodeValue = t.replace(/\[missing "[a-z0-9_.-]+" translation\]/i, text);
            }
        } catch (e) {}
    }
    (function jbWatchI18nMissing() {
        if (!/javdb/i.test(location.hostname)) return;
        try {
            const obs = new MutationObserver((muts) => {
                // [第224轮·用户反馈] 工具箱/弹窗内大规模重渲（innerHTML 一次挂几千节点）时，
                // 逐节点读 textContent 会序列化整棵子树 = O(n²) 主线程税，是切页签/切栏目卡顿真凶。
                // 扩展自身 UI 文本不参与 i18n 修复，命中自有容器直接整批跳过（每条记录一次 closest，远便宜于序列化）。
                for (const mu of muts) {
                    const tgt = mu.target;
                    if (tgt && tgt.closest && tgt.closest('#jb-hub-overlay,#emby-settings-overlay,#jb-media-overlay,#jb-resource-overlay,.preview-overlay,#jb-hub-card')) continue;
                    for (const node of mu.addedNodes) {
                        if (node.nodeType === 3) {
                            if (node.nodeValue && node.nodeValue.indexOf('[missing ') >= 0) jbFixI18nMissingText(node.parentNode || document.body);
                        } else if (node.nodeType === 1 && node.textContent && node.textContent.indexOf('[missing ') >= 0) {
                            jbFixI18nMissingText(node);
                        }
                    }
                }
            });
            const start = () => {
                if (!document.body) return setTimeout(start, 200);
                jbFixI18nMissingText(document.body);
                obs.observe(document.body, { childList: true, subtree: true });
            };
            start();
        } catch (e) {}
    })();

    // ========== 页面推广横幅（列表页顶部，关闭后 7 天内不再显示） ==========
    function addPromoBanner() {
        try {
            const dismissedUntil = GM_getValue('jb_promo_dismissed_until', 0);
            if (Date.now() < dismissedUntil) return;
            if (document.getElementById('jb-promo-banner')) return;

            // 目标位置：顶部导航栏内、ThePornDude 之后（紧邻右侧的识图/设置按钮之间）
            const navbar = document.querySelector('.navbar') || document.querySelector('.navbar-menu') || document.body;
            const tpd = ((nav) => {
                if (!nav) return null;
                if (nav !== document.body) {
                    const direct = Array.from(nav.querySelectorAll('.navbar-item, a, .nav-link, li a')).find(a => /PornDude/i.test(a.textContent || ''));
                    if (direct) return direct;
                }
                return null;
            })(navbar);
            if (!tpd) {
                // 导航栏尚未渲染完成时，等待片刻后重试一次（避免 DOMContentLoaded 前执行导致找不到锚点）
                if (!addPromoBanner._retried) {
                    addPromoBanner._retried = true;
                    setTimeout(addPromoBanner, 600);
                }
                return;
            }

            const banner = document.createElement('a');
            banner.id = 'jb-promo-banner';
            banner.href = 'https://invite.m78star.cn/#/register?code=mHlkrWyl';
            banner.target = '_blank';
            banner.rel = 'noopener noreferrer';
            banner.title = '🚀 机场 · 送 Emby 影视库';
            // 适配导航栏高度的紧凑横幅
            banner.style.cssText = 'position:relative;display:inline-flex;align-items:center;gap:8px;margin:2px 4px;padding:3px 12px;border-radius:14px;background:linear-gradient(120deg,#1a237e 0%,#4a148c 55%,#880e4f 100%);box-shadow:0 2px 8px rgba(74,20,140,0.35);color:#fff;text-decoration:none;font-size:12px;font-weight:bold;white-space:nowrap;line-height:1.5;overflow:hidden;';
            banner.innerHTML = `
                <span>🌌 M78星云机场</span>
                <span style="font-weight:400;opacity:0.9;">赠 Emby 影视库</span>
                <span style="display:inline-flex;align-items:center;gap:5px;background:linear-gradient(135deg,#7c4dff,#536dfe);padding:2px 12px;border-radius:12px;">🚀 立即注册</span>
                <span id="jb-promo-close" title="关闭（7 天内不再显示）" style="position:absolute;top:-2px;right:5px;cursor:pointer;color:rgba(255,255,255,0.6);font-size:14px;line-height:1;user-select:none;" onclick="event.stopPropagation();event.preventDefault();">×</span>
            `;
            // 插入：ThePornDude 之后（顶栏左端 ThePornDude 与右端识图/设置之间）
            if (tpd) tpd.after(banner);
            const closeBtn = banner.querySelector('#jb-promo-close');
            if (closeBtn) {
                closeBtn.onmouseenter = () => { closeBtn.style.color = 'rgba(255,255,255,0.95)'; };
                closeBtn.onmouseleave = () => { closeBtn.style.color = 'rgba(255,255,255,0.6)'; };
                closeBtn.onclick = (e) => {
                    e.stopPropagation();
                    e.preventDefault();
                    GM_setValue('jb_promo_dismissed_until', Date.now() + 7 * 24 * 3600 * 1000);
                    banner.remove();
                };
            }
        } catch (e) {
            console.log('全能助手:添加推广横幅失败', e);
        }
    }

    // [第118轮·用户指令] javdb 官方底部「官方App下载」横幅（nav.app-desktop-banner）收成右下角小图标：
    // 默认隐藏横幅，边角只留一个圆形小钮（复用横幅内的 App 图标）；
    // 【用户二改】点击不再展开横幅，直接新标签打开横幅链接（.content[data-href]）；位置上挪避开原生 TOP 钮
    function collapseAppBanner() {
        try {
            if (document.getElementById('jb-banner-dot')) return;
            const banner = document.querySelector('nav.app-desktop-banner');
            if (!banner) {
                // 横幅可能晚于 body 渲染，短轮询几次
                let n = 0;
                const t = setInterval(() => {
                    if (document.querySelector('nav.app-desktop-banner') || ++n > 40) { clearInterval(t); if (n <= 40) collapseAppBanner(); }
                }, 250);
                return;
            }
            // 1) 隐藏官方横幅 + 官方右下角 TOP 回顶钮（[第144轮·用户指令] 右侧 pill 已有回顶，官方 TOP 冗余）
            if (!document.getElementById('jb-banner-style')) {
                const st = document.createElement('style');
                st.id = 'jb-banner-style';
                st.textContent = 'nav.app-desktop-banner{display:none!important;} a.material-scrolltop{display:none!important;} .float-buttons{display:none!important;}';
                document.head.appendChild(st);
            }
            // 2) 右下角小图标：[第127轮·用户钦定] 换成官方 App 同款「番」字 logo 拆字版——
            //    白底 + 黑字 + 黑描边 + 硬阴影（动漫贴纸风），全主题统一不再随 toon 换色
            const dot = document.createElement('div');
            dot.id = 'jb-banner-dot';
            dot.title = '官方 App 下载';
            const iconHtml = '<span style="font-family:\'Microsoft YaHei\',sans-serif;font-weight:800;font-size:17px;line-height:1;color:#334155;user-select:none;">番</span>';
            // [第144轮] 官方 TOP 钮已隐藏（用户指令），番钮从避让位 58px 回到原位 10px
            // [第145轮·用户钦定] 番钮贴边：右下角零间距，只留左上圆角；四边黑描边必须完整（用户反馈：
            // 贴角时若去掉右/下边框，描边会"消失"显得缺边）——描边贴着屏幕边缘仍然可见
            // [第298轮·用户反馈] 浅/暗主题下改中性款（白/深底细灰边无硬阴影）；toon 由 CSS 覆盖回贴纸款
            dot.style.cssText = 'position:fixed;right:0;bottom:0;width:38px;height:38px;border-radius:12px 0 0 0;background:#fff;border:1.5px solid #94a3b8;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:99998;transition:transform .15s;box-sizing:border-box;';
            dot.innerHTML = iconHtml;
            dot.addEventListener('mouseenter', function() { this.style.transform = 'scale(1.1)'; });
            dot.addEventListener('mouseleave', function() { this.style.transform = 'scale(1)'; });
            // [第118轮·用户指定] 点击不再展开横幅，直接新标签打开横幅链接（链接在 .content 的 data-href，非 <a>）
            dot.addEventListener('click', (e) => {
                e.preventDefault();
                e.stopPropagation();
                const href = (banner.querySelector('.content[data-href]') || {}).dataset
                    ? banner.querySelector('.content[data-href]').dataset.href
                    : (banner.querySelector('a[href]') || {}).href;
                if (href) window.open(href, '_blank', 'noopener');
                else showToast('未找到横幅链接');
            });
            document.body.appendChild(dot);
            console.log('全能助手:底部官方横幅已收纳为小图标');
        } catch (e) {
            console.error('全能助手:收纳底部横幅失败', e);
        }
    }

    // [本轮·新增] 主题系统：6 套主题（默认/动漫卡通/暗夜霓虹/极简杂志/奶油手账/玻璃拟态），
    // html[data-jb-theme] 属性驱动，CSS 全量映射到 javdb 真实 DOM（navbar/卡片/标题/标签/详情面板）。
