            // [第348轮] 存在即覆盖（守卫会让新版 CSS 输给先建元素的旧脚本）
            {
                const st = document.getElementById('jb-theme-style') || (() => { const s = document.createElement('style'); s.id = 'jb-theme-style'; document.head.appendChild(s); return s; })();
                st.textContent = jbThemeStyleText();
            }
