            const selectHtml = (sel) => `<div style="padding:10px 14px;border-top:1px solid #f2f3f5;">
                    <div style="font-size:12px;color:#666;margin-bottom:6px;">${sel.label}</div>
                    <select id="${sel.id}" style="width:100%;height:32px;border:1px solid #d5dbe3;border-radius:6px;padding:0 6px;background:#fff;color:#333;font-size:13px;cursor:pointer;">
                        <option value="javdb" ${sel.val === 'javdb' ? 'selected' : ''}>JavDB 预览图（多图 + 演员）</option>
                        <option value="screenshot" ${sel.val === 'screenshot' ? 'selected' : ''}>预览长图（javstore/projectjav/javfree）</option>
                    </select></div>`;
            const sectionsHtml = groups.map(g => `<div style="padding:8px 14px 2px;display:flex;align-items:center;gap:8px;border-top:1px solid #f2f3f5;background:#fafbfd;">
                    <span style="width:3px;height:12px;border-radius:2px;background:${g.color};flex:none;"></span>
                    <span style="font-size:12px;font-weight:700;color:#48566b;">${g.title}</span></div>`
                + g.items.map(it => it.k ? rowHtml(it) : (it.slider ? sliderHtml(it.slider) : selectHtml(it.select))).join('')).join('');
            const panel = document.createElement('div');
            panel.id = 'jb-quick-settings';
