    // 事件委托：兜底处理导航栏 设置 按钮，即使用户脚本注入的元素被 JAVDB 重渲染也能响应
    // [第172轮] 识图按钮退役，委托只剩 #jb-nav-settings
    document.addEventListener('click', (e) => {
        const el = e.target && e.target.closest ? e.target.closest('#jb-nav-settings') : null;
        if (!el) return;
        e.preventDefault();
        e.stopPropagation();
        console.log('[JB] 委托命中点击:', el.id);
        try { jbOpenFullSettings(); }
        catch (err) { console.log('全能助手:设置打开失败', err); showToast('设置打开失败：' + (err.message || '未知错误')); }
    }, true);

    // 点击设置面板外的空白区域关闭面板；面板内部操作不会被误关闭。
    document.addEventListener('click', (e) => {
        const panel = document.getElementById('jb-quick-settings');
        if (!panel || panel.contains(e.target)) return;
        if (e.target?.closest && e.target.closest('#jb-nav-settings')) return;
        panel.remove();
    }, true);

    // 稳妥兜底：在油猴脚本菜单里注册 设置/识图 命令（即使导航栏按钮被其他扩展/脚本覆盖，也能从油猴菜单触发）
