    function jbNegCache(st) { /* [第427轮] 按服务器分家：jb_notinlib_neg_emby / jb_notinlib_neg_jellyfin */
        const __t = (st === 'jellyfin') ? 'jellyfin' : 'emby';
        if (JB_NEG_CACHE[__t] === null) { try { JB_NEG_CACHE[__t] = JSON.parse(GM_getValue('jb_notinlib_neg_' + __t, '{}') || '{}') || {}; } catch (eN9) { JB_NEG_CACHE[__t] = {}; } }
        return JB_NEG_CACHE[__t];
    }
    let SYNC_ERROR = '';
