            const ifM = pageHtml.match(/<iframe[^>]*src=["']?(https?:\/\/dash\.madou\.club\/share\/[a-zA-Z0-9]+)/i);
            if (!ifM) { if (diag) diag['麻豆'] = '文章页无播放器(可能纯图帖)'; return null; }
