    // [第181轮·用户指令] BTSearch 引擎（btsearch.love，老司机 2.8.8 同款）：
    // JSON API + 三头签名（x-timestamp/x-nonce/x-sign = MD5(sorted(params)&key=long2ice) 大写），
    // 签名算法照搬老司机 _searchBTSearch（2026-10-01 curl 实测 200 有效）
    function btFormatBytes(bytes) {
        const n = Number(bytes);
        if (!Number.isFinite(n) || n <= 0) return '';
        const units = ['B', 'KB', 'MB', 'GB', 'TB'];
        let v = n, i = 0;
        while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
        return (i === 0 ? v : v.toFixed(v >= 100 ? 0 : 1)) + ' ' + units[i];
    }
    async function btSearchBtsearch(code) {
        const base = 'https://btsearch.love';
        const searchUrl = base + '/search?keyword=' + encodeURIComponent(code);
        const timestamp = Math.floor(Date.now() / 1000).toString();
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
        let nonce = '';
        for (let i = 0; i < 8; i++) nonce += chars.charAt(Math.floor(Math.random() * chars.length));
        const params = { keyword: code, limit: '10', offset: '0', mode: '', time: '', sort: 'size', sort_type: 'desc', size: '' };
        const parts = ['timestamp=' + timestamp, 'nonce=' + nonce];
        Object.keys(params).forEach(k => parts.push(k + '=' + params[k]));
        const sign = md5(parts.sort().join('&') + '&key=long2ice').toUpperCase();
        const qs = new URLSearchParams(params).toString();
        const r = await btFetch(base + '/api/search?' + qs, {
            'Accept': 'application/json, text/plain, */*',
            'Referer': searchUrl,
            'x-timestamp': timestamp,
            'x-nonce': nonce,
            'x-sign': sign
        });
        if (!r.ok) return { url: searchUrl, data: [] };
        let json = null;
        try { json = JSON.parse(r.responseText); } catch (e) { return { url: searchUrl, data: [] }; }
        const raw = Array.isArray(json && json.data) ? json.data : (Array.isArray(json && json.data && json.data.data) ? json.data.data : []);
        const clean = (s) => String(s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
        const data = raw.map(item => {
            const hash = String(item && item.hash || '').replace(/^magnet:\?xt=urn:btih:/i, '').replace(/[^a-z0-9]/gi, '');
            if (!/^[a-f0-9]{32,40}$/i.test(hash)) return null;
            return {
                name: clean(item && item.name) || ('magnet:?xt=urn:btih:' + hash),
                magnetUrl: 'magnet:?xt=urn:btih:' + hash,
                size: btFormatBytes(item && item.size),
                date: String((item && (item.created_at || item.created_time || item.create_time)) || '').replace('T', ' ').slice(0, 16),
                src: item && item.id ? (base + '/torrent/' + encodeURIComponent(item.id) + '?keyword=' + encodeURIComponent(code)) : searchUrl
            };
        }).filter(Boolean);
        return { url: searchUrl, data };
    }

    // ==== [第181轮·用户指令] 115 网盘全家桶（老司机 Pan115 同款端点）====
    // 匹配 webapi.115.com/files/search(type=4 视频) · 离线 115.com/web/lixian add_task_url
    // 播放 115vod 官方网页 / 115 网页播放器 / PotPlayer 直链（proapi downurl + m115 RSA/XOR 加解密）
    // 改名 webapi.115.com/files/edit · 删除 webapi.115.com/rb/delete
    // 全部依赖 115.com 登录态 Cookie（GM_xmlhttpRequest 默认携带，无需 API Key）
    const jbM115_RSA_N = BigInt('0x8686980c0f5a24c4b9d43020cd2c22703ff3f450756529058b1cf88f09b8602136477198a6e2683149659bd122c33592fdb5ad47944ad1ea4d36c6b172aad6338c3bb6ac6227502d010993ac967d1aef00f0c8e038de2e4d3bc2ec368af2e9f10a6f1eda4f7262f136420c07c331b871bf139f74f3010e3c4fe57df3afb71683');
    const jbM115_RSA_E = 0x10001n;
    const jbM115_G_KTS = [240,229,105,174,191,220,191,138,26,69,232,190,125,166,115,184,222,143,231,196,69,218,134,196,155,100,139,20,106,180,241,170,56,1,53,158,38,105,44,134,0,107,79,165,54,52,98,166,42,150,104,24,242,74,253,189,107,151,143,77,143,137,19,183,108,142,147,237,14,13,72,62,215,47,136,216,254,254,126,134,80,149,79,209,235,131,38,52,219,102,123,156,126,157,122,129,50,234,182,51,222,58,169,89,52,102,59,170,186,129,96,72,185,213,129,156,248,108,132,119,255,84,120,38,95,190,232,30,54,159,52,128,92,69,44,155,118,213,27,143,204,195,184,245];
    const jbM115_KEY_S = [0x29, 0x23, 0x21, 0x5E];
    const jbM115_KEY_L = [120, 6, 173, 76, 51, 134, 93, 24, 76, 1, 63, 70];
    function jbM115ModPow(base, exponent, modulus) {
        let result = 1n; let value = base % modulus; let power = exponent;
        while (power > 0n) {
            if (power & 1n) result = (result * value) % modulus;
            value = (value * value) % modulus; power >>= 1n;
        }
        return result;
    }
    function jbM115BytesToHex(bytes) { return bytes.map(b => Number(b).toString(16).padStart(2, '0')).join(''); }
    function jbM115HexToBytes(hex) {
        const bytes = [];
        for (let i = 0; i < hex.length; i += 2) bytes.push(parseInt(hex.slice(i, i + 2), 16));
        return bytes;
    }
    function jbM115BigIntToBytes(value) {
        let hex = value.toString(16);
        if (hex.length % 2) hex = '0' + hex;
        return jbM115HexToBytes(hex);
    }
    function jbM115RsaEncrypt(text) {
        const padded = new Array(128).fill(0);
        let si = text.length - 1; let ti = padded.length;
        while (si >= 0) padded[--ti] = text.charCodeAt(si--);
        padded[--ti] = 0;
        while (ti > 2) padded[--ti] = 0xff;
        padded[--ti] = 2;
        const encrypted = jbM115ModPow(BigInt('0x' + jbM115BytesToHex(padded)), jbM115_RSA_E, jbM115_RSA_N);
        return encrypted.toString(16).padStart(256, '0');
    }
    function jbM115RsaDecrypt(text) {
        const encrypted = BigInt('0x' + jbM115BytesToHex([...text].map(c => c.charCodeAt(0))));
        const padded = jbM115BigIntToBytes(jbM115ModPow(encrypted, jbM115_RSA_E, jbM115_RSA_N));
        let sep = 1;
        while (sep < padded.length && padded[sep] !== 0) sep += 1;
        return String.fromCharCode(...padded.slice(sep + 1));
    }
    function jbM115GetKey(length, key) {
        if (key) return Array.from({ length: length }, (_, i) => ((key[i] + jbM115_G_KTS[length * i]) & 0xff) ^ jbM115_G_KTS[length * (length - 1 - i)]);
        return (length === 12 ? jbM115_KEY_L : jbM115_KEY_S).slice();
    }
    function jbM115XorEncode(source, key) {
        const remainder = source.length % 4; const result = [];
        for (let i = 0; i < remainder; i += 1) result.push(source[i] ^ key[i % key.length]);
        for (let i = remainder; i < source.length; i += 1) result.push(source[i] ^ key[(i - remainder) % key.length]);
        return result;
    }
    function jbM115SymEncode(source, key1, key2) { const result = jbM115XorEncode(source, jbM115GetKey(4, key1)); result.reverse(); return jbM115XorEncode(result, jbM115GetKey(12, key2)); }
    function jbM115SymDecode(source, key1, key2) { const result = jbM115XorEncode(source, jbM115GetKey(12, key2)); result.reverse(); return jbM115XorEncode(result, jbM115GetKey(4, key1)); }
    function jbM115StringToBytes(v) { return [...v].map(c => c.charCodeAt(0)); }
    function jbM115BytesToString(bytes) { return bytes.map(b => String.fromCharCode(b)).join(''); }
    function jbM115AsymEncode(source) {
        const chunkSize = 128 - 11; let encoded = '';
        for (let i = 0; i < Math.ceil(source.length / chunkSize); i += 1) {
            const chunk = source.slice(i * chunkSize, Math.min((i + 1) * chunkSize, source.length));
            encoded += jbM115RsaEncrypt(jbM115BytesToString(chunk));
        }
        return btoa(jbM115HexToBytes(encoded).map(b => String.fromCharCode(b)).join(''));
    }
    function jbM115AsymDecode(source) {
        const chunkSize = 128; let decoded = '';
        for (let i = 0; i < Math.ceil(source.length / chunkSize); i += 1) {
            const chunk = source.slice(i * chunkSize, Math.min((i + 1) * chunkSize, source.length));
            decoded += jbM115RsaDecrypt(jbM115BytesToString(chunk));
        }
        return jbM115StringToBytes(decoded);
    }
    function jbM115Encode(source, timestamp) {
        // 蓝鸟 md5（@require blueimp）生成会话密钥
        const key = jbM115StringToBytes(md5('!@###@#' + timestamp + 'DFDR@#@#'));
        let encoded = jbM115StringToBytes(source);
        encoded = jbM115SymEncode(encoded, key, null);
        encoded = key.slice(0, 16).concat(encoded);
        return { data: jbM115AsymEncode(encoded), key: key };
    }
    function jbM115Decode(source, key) {
        let decoded = jbM115StringToBytes(atob(source));
        decoded = jbM115AsymDecode(decoded);
        return jbM115BytesToString(jbM115SymDecode(decoded.slice(16), key, decoded.slice(0, 16)));
    }
    // 取视频直链（Pot 播放用）：POST proapi downurl（data=m115RSA(pickcode)），响应再 m115 解密
    function jbPan115DirectUrl(pickcode) {
        return new Promise((resolve, reject) => {
            const timestamp = Math.floor(Date.now() / 1000);
            const enc = jbM115Encode(JSON.stringify({ pickcode: pickcode }), timestamp);
            GM_xmlhttpRequest({
                method: 'POST',
                url: 'https://proapi.115.com/app/chrome/downurl?t=' + timestamp,
                data: 'data=' + encodeURIComponent(enc.data),
                timeout: 20000,
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'Referer': 'https://115.com/'
                },
                onload(response) {
                    try {
                        const payload = JSON.parse(response.responseText || '{}');
                        if (!payload.state) { reject(new Error(payload.msg || payload.error || ('errno:' + (payload.errno || response.status || 0)))); return; }
                        const decoded = JSON.parse(jbM115Decode(payload.data, enc.key));
                        const fileId = Object.keys(decoded)[0];
                        const directUrl = decoded[fileId] && decoded[fileId].url && decoded[fileId].url.url;
                        if (!directUrl) { reject(new Error('115 未返回可播放直链')); return; }
                        resolve(directUrl);
                    } catch (error) {
                        reject(new Error('115 直链解析失败: ' + error.message));
                    }
                },
                onerror: () => reject(new Error('115 直链请求失败')),
                ontimeout: () => reject(new Error('115 直链请求超时'))
            });
        });
    }

    const jbPan115 = {
        api: 'https://webapi.115.com/files/search',
        editApi: 'https://webapi.115.com/files/edit',
        deleteApi: 'https://webapi.115.com/rb/delete',
        videoExts: new Set(['mp4', 'mkv', 'avi', 'wmv', 'mov', 'm4v', 'ts', 'flv', 'rmvb', 'webm']),
        pendingAll: new Map(),
        listCachePrefix: 'jb_pan115_list_v1_',
        mgstagePrefixMap: {
            LUXU: '259LUXU', MIUM: '300MIUM', GANA: '200GANA', SIRO: 'SIRO', DCV: '277DCV',
            JNT: '390JNT', JAC: '390JAC', HHH: '451HHH', HLM: '436HLM', SYS: '332SYS',
            NAMA: '332NAMA', HEN: '353HEN', ARA: '261ARA', FCT: '326FCT', ERK: '420ERK',
            STH: '420STH', MLA: '476MLA', MMC: '812MMC', MY: '292MY', OERO: '892OERO'
        },
        sourceAliases: {
            PACO: ['PACO', 'PACOPACOMAMA'], PACOPACOMAMA: ['PACO', 'PACOPACOMAMA'],
            '10MU': ['10MU', '10MUSUME'], '10MUSUME': ['10MU', '10MUSUME'],
            '1PON': ['1PON', '1PONDO'], '1PONDO': ['1PON', '1PONDO'],
            CARIB: ['CARIB', 'CARIBBEANCOM'], CARIBBEANCOM: ['CARIB', 'CARIBBEANCOM'],
            HEYZO: ['HEYZO']
        },
        enabled() { try { return !!GM_getValue('jb_pan115_enabled', false); } catch (_) { return false; } },
        normalizeCode(code) { return String(code || '').trim().toUpperCase().replace(/[_\s]+/g, '-'); },
        normalizeKeepSeparator(code) { return String(code || '').trim().toUpperCase().replace(/\s+/g, '-'); },
        playUrl(pickcode) {
            const encoded = encodeURIComponent(pickcode);
            const playerMode = GM_getValue('jb_pan115_player', 'official');
            if (playerMode === '115master') return 'https://115.com/web/lixian/master/video/?pick_code=' + encoded;
            return 'https://115vod.com/?pickcode=' + encoded + '&share_id=0';
        },
        listCacheKey(code) { return this.listCachePrefix + this.normalizeKeepSeparator(code); },
        getListCached(code) {
            try {
                const raw = sessionStorage.getItem(this.listCacheKey(code));
                if (!raw) return undefined;
                const parsed = JSON.parse(raw);
                if (!Array.isArray(parsed) || !parsed.length) { sessionStorage.removeItem(this.listCacheKey(code)); return undefined; }
                return parsed;
            } catch (_) { return undefined; }
        },
        setListCached(code, value) {
            try {
                const matches = Array.isArray(value) ? value : [];
                if (!matches.length) { sessionStorage.removeItem(this.listCacheKey(code)); return; }
                sessionStorage.setItem(this.listCacheKey(code), JSON.stringify(matches));
            } catch (_) {}
        },
        sourcePattern() { return Object.keys(this.sourceAliases).sort((a, b) => b.length - a.length).join('|'); },
        sourceGroup(source) { return this.sourceAliases[String(source || '').toUpperCase()] || [String(source || '').toUpperCase()].filter(Boolean); },
        uncensoredParts(code) {
            const normalized = this.normalizeKeepSeparator(code);
            const match = normalized.match(/^(\d{6})([-_])(\d{2,3})(?:[-_]([A-Z0-9]+))?$/);
            return match ? { date: match[1], sep: match[2], num: match[3], source: match[4] || '' } : null;
        },
        uncensoredDigitKey(code) {
            const parts = this.uncensoredParts(code);
            return parts ? (parts.date + parts.sep + parts.num) : '';
        },
        fc2Number(code) {
            const normalized = this.normalizeKeepSeparator(code);
            const match = normalized.match(/^FC2[-_\s]?(?:PPV[-_\s]?)?(\d{6,9})$/i);
            return match ? match[1] : '';
        },
        extractCode(text, fallbackCode) {
            const fc2 = String(text || '').match(/\bFC2[-_\s]?(?:PPV[-_\s]?)?(\d{6,9})\b/i);
            if (fc2) return 'FC2-PPV-' + fc2[1];
            const sourcePattern = this.sourcePattern();
            const tail = String(text || '').match(new RegExp('\\b(\\d{6})([-_])(\\d{2,3})[-_\\s]*(' + sourcePattern + ')\\b', 'i'));
            if (tail) {
                const source = tail[4].toUpperCase(); const sep = tail[2] === '_' ? '_' : '-';
                return tail[1] + sep + tail[3] + '-' + source;
            }
            const head = String(text || '').match(new RegExp('\\b(' + sourcePattern + ')[-_\\s]*(\\d{6})([-_])(\\d{2,3})\\b', 'i'));
            if (head) {
                const source = head[1].toUpperCase(); const sep = head[3] === '_' ? '_' : '-';
                return head[2] + sep + head[4] + '-' + source;
            }
            return fallbackCode || '';
        },
        searchKeyword(code) {
            const fc2 = this.fc2Number(code);
            if (fc2) return fc2;
            return String(code || '').trim().toLowerCase().replace(/^fc2-(?:ppv-)?/, '');
        },
        searchVariants(code) {
            const normalized = this.normalizeKeepSeparator(code);
            const variants = [normalized];
            const compact = normalized.replace(/[-_]/g, '');
            if (compact !== normalized) variants.push(compact);
            const fc2 = this.fc2Number(normalized);
            if (fc2) variants.push('FC2-' + fc2, 'FC2-PPV-' + fc2, fc2);
            const mgstage = normalized.match(/^(\d{3})([A-Z]{2,10})-(\d{2,6})$/);
            if (mgstage && Object.values(this.mgstagePrefixMap).includes(mgstage[1] + mgstage[2])) variants.push(mgstage[2] + '-' + mgstage[3]);
            const shortMgstage = normalized.match(/^([A-Z]{2,10})-(\d{2,6})$/);
            if (shortMgstage && this.mgstagePrefixMap[shortMgstage[1]]) variants.push(this.mgstagePrefixMap[shortMgstage[1]] + '-' + shortMgstage[2]);
            const uncensored = this.uncensoredParts(normalized);
            if (uncensored) {
                variants.push(uncensored.date + uncensored.sep + uncensored.num);
                if (uncensored.source) {
                    this.sourceGroup(uncensored.source).forEach(source => {
                        variants.push(uncensored.date + uncensored.sep + uncensored.num + '-' + source);
                        variants.push(source + '-' + uncensored.date + uncensored.sep + uncensored.num);
                    });
                }
            }
            return [...new Set(variants.filter(Boolean))];
        },
        codeRegex(code) {
            const fc2 = this.fc2Number(code);
            if (fc2) return new RegExp('(^|[^A-Z0-9])(?:FC2[-_\\s]?(?:PPV[-_\\s]?)?' + fc2 + '|' + fc2 + ')([^A-Z0-9]|$)', 'i');
            const digitKey = this.uncensoredDigitKey(code);
            if (digitKey) {
                const parts = this.uncensoredParts(code); const sep = parts.sep === '_' ? '_' : '-';
                return new RegExp('(^|[^0-9])' + parts.date + sep + parts.num + '([^0-9]|$)', 'i');
            }
            const patterns = [];
            const add = (value) => {
                const normalized = this.normalizeCode(value);
                if (!normalized) return;
                const escaped = normalized.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/[-_]/g, '[-_\\s]?');
                patterns.push(escaped, normalized.replace(/[-_]/g, ''));
            };
            this.searchVariants(code).forEach(add);
            return new RegExp('(?:' + [...new Set(patterns)].join('|') + ')', 'i');
        },
        isVideoName(name) {
            const ext = String(name || '').split('.').pop().toLowerCase();
            return this.videoExts.has(ext);
        },
        parseSize(value) {
            if (value == null || value === '') return 0;
            if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
            const text = String(value).trim().replace(/,/g, '');
            const unitMatch = text.match(/^([\d.]+)\s*(b|kb|mb|gb|tb)$/i);
            if (unitMatch) {
                const amount = Number(unitMatch[1]);
                const unit = unitMatch[2].toLowerCase();
                const power = { b: 0, kb: 1, mb: 2, gb: 3, tb: 4 }[unit] || 0;
                return Number.isFinite(amount) ? Math.round(amount * Math.pow(1024, power)) : 0;
            }
            const numeric = Number(text);
            return Number.isFinite(numeric) ? numeric : 0;
        },
        formatSize(bytes) {
            const size = this.parseSize(bytes);
            if (!size) return '';
            const units = ['B', 'KB', 'MB', 'GB', 'TB'];
            let value = size; let index = 0;
            while (value >= 1024 && index < units.length - 1) { value /= 1024; index += 1; }
            const digits = index >= 3 ? 2 : index >= 2 ? 1 : 0;
            return value.toFixed(digits).replace(/\.0+$/, '') + ' ' + units[index];
        },
        lowPriorityReason(item) {
            const name = String(item && item.name || '');
            const size = this.parseSize(item && item.size);
            const previewName = /(?:^|[.\-_\s])(?:tp|trailer|sample|preview|pv|cm|予告|预告|試看|试看)(?:[.\-_\s]|$)/i.test(name);
            if (previewName) return '疑似预告/样片';
            if (size > 0 && size < 180 * 1024 * 1024) return '小体积文件';
            return '';
        },
        candidateRank(item) {
            const reason = this.lowPriorityReason(item);
            const size = this.parseSize(item && item.size);
            return (reason ? 1000 : 0) - Math.min(size / Math.pow(1024, 3), 100);
        },
        flattenFiles(payload) {
            const candidates = [payload && payload.data, payload && payload.data && payload.data.list, payload && payload.data && payload.data.files, payload && payload.data && payload.data.items, payload && payload.files, payload && payload.list];
            const arr = candidates.find(Array.isArray) || [];
            return arr.map(item => ({
                name: item.n || item.name || item.file_name || item.filename || item.title || '',
                pickcode: item.pc || item.pickcode || item.pick_code || item.pickCode || item.pick || '',
                fileId: item.fid || item.file_id || item.fileId || item.id || '',
                size: this.parseSize(item.s || item.size || item.file_size || item.fileSize || item.fs || item.bytes),
                raw: item
            })).filter(item => item.name);
        },
        requestSearch(keyword) {
            const query = new URLSearchParams({ search_value: keyword, limit: '50', offset: '0', type: '4' });
            return new Promise((resolve, reject) => {
                GM_xmlhttpRequest({
                    method: 'GET',
                    url: this.api + '?' + query.toString(),
                    timeout: 15000,
                    headers: { 'Accept': 'application/json, text/plain, */*' },
                    onload: (r) => {
                        try { resolve(JSON.parse(r.responseText)); }
                        catch (_) { reject(new Error('115 返回不是 JSON，可能未登录')); }
                    },
                    onerror: () => reject(new Error('115 请求失败')),
                    ontimeout: () => reject(new Error('115 请求超时'))
                });
            });
        },
        async searchAll(code) {
            const matcher = this.codeRegex(code);
            const seen = new Set(); const matches = [];
            const keywords = [...new Set(this.searchVariants(code).map(item => this.searchKeyword(item)).filter(Boolean))];
            for (const keyword of keywords) {
                const payload = await this.requestSearch(keyword);
                const state = payload ? (payload.state !== undefined ? payload.state : payload.success) : undefined;
                if (state === false) {
                    const msg = payload.error || payload.message || payload.errno || '115 查询失败';
                    throw new Error(String(msg));
                }
                for (const item of this.flattenFiles(payload)) {
                    const key = item.pickcode || item.name;
                    if (seen.has(key)) continue;
                    seen.add(key);
                    if (matcher.test(item.name) && this.isVideoName(item.name) && item.pickcode) {
                        item.lowPriorityReason = this.lowPriorityReason(item);
                        item.sizeText = this.formatSize(item.size);
                        matches.push(item);
                    }
                }
            }
            return matches.sort((a, b) => this.candidateRank(a) - this.candidateRank(b));
        },
        searchAllCached(code) {
            const normalized = this.normalizeKeepSeparator(code);
            if (!normalized) return Promise.resolve([]);
            const cached = this.getListCached(normalized);
            if (cached !== undefined) return Promise.resolve(cached);
            if (this.pendingAll.has(normalized)) return this.pendingAll.get(normalized);
            const task = this.searchAll(normalized)
                .then(matches => { this.setListCached(normalized, matches); return matches; })
                .finally(() => this.pendingAll.delete(normalized));
            this.pendingAll.set(normalized, task);
            return task;
        },
        postForm(url, body, label) {
            return new Promise((resolve, reject) => {
                GM_xmlhttpRequest({
                    method: 'POST',
                    url: url,
                    data: body.toString(),
                    timeout: 15000,
                    headers: {
                        'Accept': 'application/json, text/plain, */*',
                        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
                    },
                    onload: (r) => {
                        try {
                            const payload = JSON.parse(r.responseText || '{}');
                            const ok = payload.state === true || payload.success === true || payload.errno === 0;
                            if (ok) resolve(payload);
                            else reject(new Error(String(payload.error || payload.message || payload.errno || (label + '失败'))));
                        } catch (_) { reject(new Error(label + '返回不是 JSON')); }
                    },
                    onerror: () => reject(new Error(label + '请求失败')),
                    ontimeout: () => reject(new Error(label + '请求超时'))
                });
            });
        },
        deleteFile(fileId) {
            const fid = String(fileId || '').trim();
            if (!fid) return Promise.reject(new Error('缺少 115 文件 ID，无法删除'));
            const body = new URLSearchParams();
            body.set('fid[0]', fid); body.set('ignore_warn', '1');
            return this.postForm(this.deleteApi, body, '115 删除');
        },
        renameFile(fileId, newName) {
            const fid = String(fileId || '').trim();
            const fileName = String(newName || '').trim().replace(/[\\/:*?"<>|]/g, ' ');
            if (!fid) return Promise.reject(new Error('缺少 115 文件 ID，无法改名'));
            if (!fileName) return Promise.reject(new Error('新文件名为空'));
            return this.postForm(this.editApi, new URLSearchParams({ fid: fid, file_name: fileName }), '115 改名');
        }
    };

    // 115 离线推送（磁力行「115」按钮）：space 拿 sign/time → lixian add_task_url
    function jbPan115OfflinePush(maglink) {
        maglink = String(maglink || '').substring(0, 60); // magnet:?xt=urn:btih:<40hex> 恰 60 字符，去掉 &dn 等尾巴
        if (!/^magnet:/i.test(maglink)) { showToast('不是有效的磁力链接'); return; }
        showToast('正在推送到 115 离线…');
        GM_xmlhttpRequest({
            method: 'GET',
            url: 'https://115.com/?ct=offline&ac=space&_=' + Date.now(),
            timeout: 15000,
            headers: {
                'Accept': 'application/json, text/plain, */*',
                'Referer': 'https://115.com/?tab=offline&mode=wangpan'
            },
            onload(r) {
                if (!r.responseText || r.responseText.includes('<html') || r.responseText.includes('html>')) {
                    showToast('⚠️ 115 未登录，请先登录 115.com'); return;
                }
                let json = null;
                try { json = JSON.parse(r.responseText); } catch (_) {}
                if (!json || !json.sign || !json.time) { showToast('⚠️ 115 签名获取异常，请确认已登录 115.com'); return; }
                GM_xmlhttpRequest({
                    method: 'POST',
                    url: 'https://115.com/web/lixian/?ct=lixian&ac=add_task_url',
                    timeout: 20000,
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
                        'Accept': 'application/json, text/javascript, */*; q=0.01',
                        'Origin': 'https://115.com',
                        'Referer': 'https://115.com/?tab=offline&mode=wangpan',
                        'X-Requested-With': 'XMLHttpRequest'
                    },
                    data: 'url=' + encodeURIComponent(maglink) + '&uid=&sign=' + encodeURIComponent(json.sign) + '&time=' + json.time,
                    onload(r2) {
                        let res = null;
                        try { res = JSON.parse(r2.responseText); } catch (_) {}
                        if (!res) { showToast('⚠️ 115 离线失败：返回异常（登录失效或跨源未放行）'); return; }
                        if (res.state) { showToast('✅ 115 离线成功，任务已添加'); return; }
                        const msg = res.errcode === '911' ? '账号使用异常，请手工验证' : (res.error_msg || res.msg || res.error || '未知错误');
                        showToast('⚠️ 115 离线失败：' + msg);
                    },
                    onerror() { showToast('⚠️ 115 离线失败：推送请求失败'); },
                    ontimeout() { showToast('⚠️ 115 离线失败：推送请求超时'); }
                });
            },
            onerror() { showToast('⚠️ 115 签名请求失败（请确认已登录 115.com）'); },
            ontimeout() { showToast('⚠️ 115 签名请求超时'); }
        });
    }

    // 115 Pot 直链播放：直链 + UA/Referer 参数写剪贴板，potplayer:///current/clipboard 拉起
    async function jbPan115PotPlay(pickcode, title) {
        const directUrl = await jbPan115DirectUrl(pickcode);
        const cleanTitle = String(title || '').replace(/[\r\n]/g, ' ').split('"').join(' ').trim();
        const command = [
            'potplayer://' + encodeURI(directUrl),
            '/current',
            '/user_agent="' + String(navigator.userAgent).replace(/[\r\n]/g, ' ').split('"').join(' ') + '"',
            '/referer="https://115.com/"',
            cleanTitle ? '/title="' + cleanTitle + '"' : ''
        ].filter(Boolean).join(' ');
        try {
            if (navigator.clipboard) navigator.clipboard.writeText(command);
            else throw new Error('no clipboard');
        } catch (_) {
            const ta = document.createElement('textarea');
            ta.value = command; document.body.appendChild(ta); ta.select();
            try { document.execCommand('copy'); } catch (_) {}
            ta.remove();
        }
        const a = document.createElement('a');
        a.href = 'potplayer:///current/clipboard';
        document.body.appendChild(a); a.click(); a.remove();
        showToast('PotPlayer 播放指令已复制剪贴板');
        return directUrl;
    }

    // 115 匹配面板：搜索用户 115 网盘内该番号的视频文件，支持播放/改名/删除
    function jbPan115MatchPanel(videoCode) {
        if (!jbPan115.enabled()) { showToast('请先在设置中开启「115 网盘」'); return; }
        const code = String(videoCode || '').trim();
        if (!code) { showToast('缺少番号，无法匹配'); return; }
        const esc115 = (s) => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        const cover = (document.querySelector('.column-video-cover img') || {}).src || '';
        const btnStyle = 'padding:4px 10px;border:1px solid #cbd5e1;border-radius:6px;background:#fff;color:#334155;font-size:12px;font-weight:600;cursor:pointer;white-space:nowrap;';
        const bodyHtml = '<div style="display:flex;gap:14px;align-items:flex-start;">'
            + (cover ? '<img src="' + esc115(cover) + '" style="width:110px;border-radius:8px;flex:none;border:1px solid #e2e8f0;" onerror="this.remove()">' : '')
            + '<div style="flex:1;min-width:0;" id="jb-pan115-body"><div class="jb-bt-status">正在搜索 115 网盘（需已登录 115.com）…</div></div></div>';
        showModal(code + ' · 115 网盘匹配', bodyHtml);
        const renderRows = (matches) => {
            const body = document.getElementById('jb-pan115-body');
            if (!body) return;
            if (!matches.length) {
                body.innerHTML = '<div class="jb-bt-status">115 网盘中没有匹配到「' + esc115(code) + '」的视频文件。<br><span style="font-size:12px;color:#94a3b8;">可先用磁力行「115」按钮离线下载，稍后再来匹配。</span></div>';
                return;
            }
            body.innerHTML = '<div style="font-size:12px;color:#64748b;margin-bottom:8px;">匹配到 ' + matches.length + ' 个视频文件（点击「播放」按设置的 115 播放方式打开）</div>'
                + matches.map((item, idx) => {
                    const reason = item.lowPriorityReason ? ' <span style="color:#f59e0b;font-size:11px;">⚠ ' + esc115(item.lowPriorityReason) + '</span>' : '';
                    return '<div style="display:flex;align-items:center;gap:8px;padding:8px 10px;border:1px solid #e2e8f0;border-radius:8px;margin-bottom:6px;background:#f8fafc;">'
                        + '<div style="flex:1;min-width:0;font-size:12.5px;font-weight:600;color:#172033;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + esc115(item.name) + '">' + esc115(item.name) + reason + '</div>'
                        + '<span style="flex:none;font-size:11.5px;color:#64748b;">' + esc115(item.sizeText || '') + '</span>'
                        + '<button type="button" data-act="play" data-idx="' + idx + '" style="' + btnStyle + '">▶ 播放</button>'
                        + '<button type="button" data-act="rename" data-idx="' + idx + '" style="' + btnStyle + '">✏ 改名</button>'
                        + '<button type="button" data-act="del" data-idx="' + idx + '" style="' + btnStyle + ';color:#dc2626;border-color:#fecaca;">🗑 删除</button>'
                        + '</div>';
                }).join('');
            body.onclick = (e) => {
                const btn = e.target && e.target.closest ? e.target.closest('button[data-act]') : null;
                if (!btn) return;
                const item = matches[parseInt(btn.dataset.idx, 10)];
                if (!item) return;
                const act = btn.dataset.act;
                if (act === 'play') {
                    const mode = GM_getValue('jb_pan115_player', 'official');
                    if (mode === 'pot') {
                        btn.disabled = true; btn.textContent = '解析中…';
                        jbPan115PotPlay(item.pickcode, item.name).catch(err => {
                            showToast('⚠️ ' + err.message);
                            btn.disabled = false; btn.textContent = '▶ 播放';
                        });
                    } else {
                        window.open(jbPan115.playUrl(item.pickcode), '_blank');
                    }
                } else if (act === 'rename') {
                    const newName = prompt('修改文件名（115 网盘）：', item.name);
                    if (newName == null || !newName.trim() || newName.trim() === item.name) return;
                    btn.disabled = true;
                    jbPan115.renameFile(item.fileId, newName.trim()).then(() => {
                        item.name = newName.trim();
                        showToast('✅ 已改名');
                        renderRows(matches);
                    }).catch(err => { showToast('⚠️ ' + err.message); btn.disabled = false; });
                } else if (act === 'del') {
                    if (!confirm('确定从 115 网盘删除该文件吗？\n' + item.name)) return;
                    btn.disabled = true;
                    jbPan115.deleteFile(item.fileId).then(() => {
                        matches.splice(parseInt(btn.dataset.idx, 10), 1);
                        showToast('✅ 已删除');
                        renderRows(matches);
                    }).catch(err => { showToast('⚠️ ' + err.message); btn.disabled = false; });
                }
            };
        };
        jbPan115.searchAllCached(code).then(renderRows).catch(err => {
            const body = document.getElementById('jb-pan115-body');
            if (body) body.innerHTML = '<div class="jb-bt-status">⚠️ ' + esc115(err.message) + '<br><span style="font-size:12px;color:#94a3b8;">请确认已登录 115.com（浏览器内打开 115.com 能看到网盘首页）</span></div>';
        });
    }

    // 磁力行「115」按钮：事件委托（renderMagnetListHTML 聚合行 + btRenderItems 聚合列表共用）
    let jbPan115RowBound = false;
