    // ==== [第182轮·用户指令] 消息中心 + 远程弹窗公告 ====
    // 消息来源：①媒体库更新（弹窗期间检测到服务器内容变化）②资讯库新文章（打开资讯库时对比）
    // ③作品库新作品（自动检测有新增）④远程推送（NAS 静态 JSON，30 分钟轮询）
    // 弹窗公告：远程 announcements[] 内 modal 条目，未读且在展示窗口内 → 页面加载后自动 showModal 一次
    // 远程 JSON 格式（用户在 NAS javdb-static/jb/notice.json 自行编辑）：
    // { "messages":[{"id":"m1","title":"标题","text":"内容","time":"2026-10-01 10:00"}],
    //   "announcements":[{"id":"a1","title":"公告","body":"支持HTML","modal":true,"start":"2026-10-01","end":"2026-10-08"}] }
    // 远程端点可配置（GM 键 jb_msg_api，默认 NAS 域名；域名变更时无需改代码）：
    // 设置方式：Tampermonkey 菜单/控制台无 GM 入口，暂用默认值，需要时在源码改这一行
    const JB_MSG_API = (function () { try { return GM_getValue('jb_msg_api', '') || 'https://javdb.dmdx.cc/jb/notice.json'; } catch (_) { return 'https://javdb.dmdx.cc/jb/notice.json'; } })();
    const JB_MSG_TYPE_COLORS = { '媒体库': '#2563eb', '资讯': '#b45309', '作品库': '#16a34a', '远程': '#e11d48', '想看': '#ea580c', '演员库': '#0891b2', '系列库': '#7c3aed', '资源库': '#0d9488' }; // [第406轮·用户反馈4] 演员库/系列库独立通知类型；[第441轮] 每日检测汇总补专属色
    // [第304轮·强制更新] 语义化版本比较：a<b 返回 -1
    function jbVerCompare(a, b) {
        const pa = String(a || '').split('.'), pb = String(b || '').split('.');
        for (let i = 0; i < Math.max(pa.length, pb.length); i++) {
            const x = parseInt(pa[i], 10) || 0, y = parseInt(pb[i], 10) || 0;
            if (x !== y) return x < y ? -1 : 1;
        }
        return 0;
    }
