                    /* [第393轮·用户反馈] 名单带性别（女=粉/男=蓝，同预览图演员栏）与收藏高亮（橙） */
                    const __entries = (__ab ? [...__ab.querySelectorAll('a[href*="/actors/"]')] : []).map(x => { const __n = (x.textContent || '').trim(); if (!__n) return null; return { n: __n, male: !x.classList.contains('actor-female'), fav: x.classList.contains('jb-fav-actor') }; }).filter(Boolean);
                    if (!__entries.length) { showToast('未找到演员'); return; }
                    const __cp = (n) => { (navigator.clipboard ? navigator.clipboard.writeText(n) : Promise.reject()).then(() => showToast('已复制演员：' + n)).catch(() => showToast('复制失败')); };
                    if (__entries.length === 1) { __cp(__entries[0].n); return; }
