                        b.style.cssText = 'border:none;background:transparent;color:' + __col + ';font-weight:700;font-size:13px;padding:7px 12px;border-radius:8px;cursor:pointer;text-align:left;font-family:inherit;white-space:nowrap;';
                        b.onmouseenter = () => { b.style.background = 'rgba(233,30,99,.1)'; };
                        b.onmouseleave = () => { b.style.background = 'transparent'; };
