                    b.style.cssText = `display:inline-flex;align-items:center;position:relative;padding:7px 16px;border-radius:8px;border:1px solid ${color}33;background:${color}14;color:${color};font-size:13px;font-weight:600;cursor:pointer;transition:background .15s;white-space:nowrap;line-height:1;`;
                    b.onmouseenter = () => b.style.background = color + '26';
